import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import api from '../services/api';

const SolicitarRecuperacion = () => {
  const [email, setEmail] = useState('');
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');
    setError('');

    try {
      const response = await api.post('/password/solicitar', { email });
      setMessage(response.data.message);
      if (response.data.success !== false) {
        setEmail('');
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Error al enviar la solicitud');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#f8fafc] px-4">
      <div className="bg-white w-full max-w-md rounded-xl p-8 border border-[#bec9bf] shadow-lg">
        <div className="flex flex-col items-center mb-8">
          <img src="/logosena.png" alt="Logo SENA" className="w-24 h-24 mb-4 object-contain" />
          <h1 className="text-2xl font-bold text-[#00643c] text-center">Recuperar Contraseña</h1>
          <p className="text-sm text-[#45474c] text-center mt-2">
            Ingresa tu correo electrónico y te enviaremos un enlace para restablecer tu contraseña.
          </p>
        </div>

        {message && (
          <div className="mb-4 p-3 rounded-lg bg-green-100 text-green-700 text-center text-sm">
            {message}
          </div>
        )}
        
        {error && (
          <div className="mb-4 p-3 rounded-lg bg-red-100 text-red-700 text-center text-sm">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label className="block text-sm font-medium text-[#3f4942] mb-1">
              Correo electrónico
            </label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              className="w-full px-4 py-2 border border-[#bec9bf] rounded-lg focus:outline-none focus:ring-2 focus:ring-[#00643c] focus:border-transparent"
              placeholder="correo@ejemplo.com"
            />
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-[#00643c] text-white font-bold py-3 rounded-lg hover:bg-[#004a2b] transition-all disabled:opacity-70"
          >
            {loading ? 'Enviando...' : 'Enviar enlace de recuperación'}
          </button>

          <div className="text-center">
            <Link to="/login" className="text-sm text-[#00643c] hover:underline">
              Volver al inicio de sesión
            </Link>
          </div>
        </form>
      </div>
    </div>
  );
};

export default SolicitarRecuperacion;
